package org.novasos.healthysv2.laboratory;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import com.fasterxml.jackson.databind.*;import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;import org.novasos.healthysv2.TestcontainersConfiguration;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.*;import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;import org.springframework.context.annotation.*;import org.springframework.http.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.oauth2.jwt.*;import org.springframework.test.context.ActiveProfiles;import org.springframework.test.web.servlet.MockMvc;import org.springframework.transaction.annotation.Transactional;
@ActiveProfiles("test")@SpringBootTest(properties={"spring.security.oauth2.resourceserver.jwt.issuer-uri=https://keycloak.example/realms/healthys","spring.security.oauth2.resourceserver.jwt.audiences=healthys-backend-apps","healthys.security.api-client-id=healthys-backend-apps","healthys.security.cors.allowed-origins=http://localhost:5173"})@AutoConfigureMockMvc@Import({TestcontainersConfiguration.class,LaboratoryApiIntegrationTests.JwtFixtures.class})@Transactional class LaboratoryApiIntegrationTests{
 static final UUID ADMIN=UUID.fromString("60000000-0000-0000-0000-000000000001");@Autowired MockMvc mvc;@Autowired JdbcTemplate jdbc;@Autowired ObjectMapper json;
 @Test void executesTheCompleteLaboratoryWorkflow()throws Exception{Graph g=graph();JsonNode order=create(g);UUID orderId=id(order,"id"),itemId=id(order.path("items").get(0),"id");mvc.perform(post("/api/v1/lab-orders/{order}/results",orderId).header(HttpHeaders.AUTHORIZATION,"Bearer admin").contentType(MediaType.APPLICATION_JSON).content("{\"performedBy\":\"%s\"}".formatted(g.professional))).andExpect(status().isUnprocessableContent()).andExpect(jsonPath("$.code").value("SPECIMENS_INCOMPLETE"));String specimenBody=mvc.perform(post("/api/v1/lab-orders/{order}/items/{item}/specimens",orderId,itemId).header(HttpHeaders.AUTHORIZATION,"Bearer admin").contentType(MediaType.APPLICATION_JSON).content("{\"specimenNumber\":\"SP-API-001\",\"specimenType\":\"BLOOD\",\"collectedBy\":\"%s\"}".formatted(g.professional))).andExpect(status().isCreated()).andExpect(jsonPath("$.status").value("COLLECTED")).andReturn().getResponse().getContentAsString();UUID specimenId=id(json.readTree(specimenBody),"id");mvc.perform(post("/api/v1/lab-orders/{order}/specimens/{specimen}/receive",orderId,specimenId).header(HttpHeaders.AUTHORIZATION,"Bearer admin")).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("RECEIVED"));String resultBody=mvc.perform(post("/api/v1/lab-orders/{order}/results",orderId).header(HttpHeaders.AUTHORIZATION,"Bearer admin").contentType(MediaType.APPLICATION_JSON).content("{\"performedBy\":\"%s\",\"notes\":\"Automated CBC\"}".formatted(g.professional))).andExpect(status().isCreated()).andExpect(jsonPath("$.status").value("DRAFT")).andReturn().getResponse().getContentAsString();UUID resultId=id(json.readTree(resultBody),"id");mvc.perform(post("/api/v1/lab-orders/{order}/results/{result}/items",orderId,resultId).header(HttpHeaders.AUTHORIZATION,"Bearer admin").contentType(MediaType.APPLICATION_JSON).content("{\"labOrderItemId\":\"%s\",\"parameterCatalogId\":\"%s\",\"value\":\"12.5\",\"unit\":\"g/dL\",\"referenceMin\":12,\"referenceMax\":16,\"abnormalFlag\":\"NORMAL\"}".formatted(itemId,g.parameter))).andExpect(status().isCreated()).andExpect(jsonPath("$.value").value("12.5"));mvc.perform(post("/api/v1/lab-orders/{order}/results/{result}/validate",orderId,resultId).header(HttpHeaders.AUTHORIZATION,"Bearer admin").contentType(MediaType.APPLICATION_JSON).content("{\"validatedBy\":\"%s\"}".formatted(g.professional))).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("FINAL"));mvc.perform(get("/api/v1/lab-orders/{id}",orderId).header(HttpHeaders.AUTHORIZATION,"Bearer admin")).andExpect(status().isOk()).andExpect(jsonPath("$.status").value("COMPLETED")).andExpect(jsonPath("$.items[0].status").value("COMPLETED")).andExpect(jsonPath("$.results[0].items.length()").value(1));mvc.perform(post("/api/v1/lab-orders/{order}/items/{item}/specimens",orderId,itemId).header(HttpHeaders.AUTHORIZATION,"Bearer admin").contentType(MediaType.APPLICATION_JSON).content("{\"specimenNumber\":\"SP-LATE\",\"specimenType\":\"BLOOD\",\"collectedBy\":\"%s\"}".formatted(g.professional))).andExpect(status().isUnprocessableContent()).andExpect(jsonPath("$.code").value("LAB_ORDER_CLOSED"));org.assertj.core.api.Assertions.assertThat(jdbc.queryForObject("select count(*) from audit.audit_log where module='LABORATORY' and entity_id=?",Integer.class,orderId)).isEqualTo(6);}
 @Test void validatesOrderAndSupportsSearch()throws Exception{Graph g=graph();JsonNode order=create(g);mvc.perform(get("/api/v1/lab-orders").header(HttpHeaders.AUTHORIZATION,"Bearer admin").param("patientId",g.patient.toString())).andExpect(status().isOk()).andExpect(jsonPath("$.content[0].id").value(order.path("id").asText()));mvc.perform(post("/api/v1/lab-orders").header(HttpHeaders.AUTHORIZATION,"Bearer admin").contentType(MediaType.APPLICATION_JSON).content("{\"patientId\":\"%s\",\"orderingProfessionalId\":\"%s\",\"priority\":\"ROUTINE\",\"items\":[]}".formatted(g.patient,g.professional))).andExpect(status().isBadRequest()).andExpect(jsonPath("$.code").value("VALIDATION_FAILED"));}
 private JsonNode create(Graph g)throws Exception{String body="{\"patientId\":\"%s\",\"orderingProfessionalId\":\"%s\",\"laboratoryOrganizationId\":\"%s\",\"priority\":\"URGENT\",\"items\":[{\"labExamCatalogId\":\"%s\",\"instructions\":\"Fasting\"}]}".formatted(g.patient,g.professional,g.organization,g.exam);return json.readTree(mvc.perform(post("/api/v1/lab-orders").header(HttpHeaders.AUTHORIZATION,"Bearer admin").contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().isCreated()).andExpect(jsonPath("$.items[0].examCode").value("CBC")).andReturn().getResponse().getContentAsString());}private UUID id(JsonNode node,String field){return UUID.fromString(node.path(field).asText());}
 private Graph graph(){UUID pp=person(),lp=person(),patient=UUID.randomUUID(),professional=UUID.randomUUID(),organization=UUID.randomUUID(),exam=UUID.randomUUID(),parameter=UUID.randomUUID();jdbc.update("insert into patient.patient(id,person_id,patient_number) values (?,?,?)",patient,pp,"PAT-"+patient);jdbc.update("insert into professional.professional(id,person_id,professional_number,professional_type,status) values (?,?,?,?,?)",professional,lp,"PRO-"+professional,"LAB_TECHNICIAN","ACTIVE");jdbc.update("insert into organization.organization(id,organization_number,name) values (?,?,?)",organization,"ORG-"+organization,"Lab");jdbc.update("insert into catalog.laboratory_exam_catalog(id,code,name,specimen_type,active) values (?,?,?,?,?)",exam,"CBC","Complete blood count","BLOOD",true);jdbc.update("insert into catalog.laboratory_parameter_catalog(id,exam_id,code,name,unit) values (?,?,?,?,?)",parameter,exam,"HGB","Hemoglobin","g/dL");return new Graph(patient,professional,organization,exam,parameter);}private UUID person(){UUID id=UUID.randomUUID();jdbc.update("insert into identity.person(id,person_number,first_name,last_name,status) values (?,?,?,?,?)",id,"PER-"+id,"Lab","User","ACTIVE");return id;}record Graph(UUID patient,UUID professional,UUID organization,UUID exam,UUID parameter){}
 @TestConfiguration(proxyBeanMethods=false)static class JwtFixtures{@Bean JwtDecoder jwtDecoder(){return token->{Instant now=Instant.now();return Jwt.withTokenValue(token).header("alg","RS256").subject(ADMIN.toString()).issuer("https://keycloak.example/realms/healthys").audience(List.of("healthys-backend-apps")).issuedAt(now).expiresAt(now.plusSeconds(300)).claim("realm_access",Map.of("roles",List.of("PLATFORM_ADMIN"))).claim("resource_access",Map.of()).build();};}}
}
